"""Lightweight validation script for the upstream pipeline outputs.

Validated artifacts (all relative to the workspace ``outputs/`` folder):

* ``t01_selected_indicators.csv``
* ``t05_clean_stops.csv``
* ``t08_pois_clean.csv``
* ``t10_accessibility_scores.csv``
* ``t13_city_clusters.csv``

Each check is executed independently and recorded as an entry with
``check_name``, ``passed`` and ``message``.  A missing, empty or malformed
output produces a *failed* check instead of an exception, so the script always
finishes and always writes ``outputs/t14_validation_summary.json``.

Usage (from the workspace root)::

    python src/validate_outputs.py

Exit code is 0 when every check passes and 1 otherwise (the summary file is
written in both cases).
"""

from __future__ import annotations

import csv
import json
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(SCRIPT_DIR)
OUTPUTS_DIR = os.path.join(BASE_DIR, "outputs")
SUMMARY_FILENAME = "t14_validation_summary.json"

T01 = "t01_selected_indicators.csv"
T05 = "t05_clean_stops.csv"
T08 = "t08_pois_clean.csv"
T10 = "t10_accessibility_scores.csv"
T13 = "t13_city_clusters.csv"

EXPECTED_DIRECTIONS = {"lower_is_better", "higher_is_better", "contextual"}

# Caches so that every file is read at most once per run.
_CACHE: dict[str, list[dict]] = {}


class CheckFailure(Exception):
    """Raised by a check to report a failure (never propagates)."""


# --------------------------------------------------------------------------- #
# I/O helpers
# --------------------------------------------------------------------------- #
def output_path(filename: str) -> str:
    return os.path.join(OUTPUTS_DIR, filename)


def load_rows(filename: str, required_columns: tuple[str, ...] = ()) -> list[dict]:
    """Read a CSV output, raising :class:`CheckFailure` on any structural problem."""
    path = output_path(filename)
    if not os.path.exists(path):
        raise CheckFailure(f"{filename} is missing (expected at {path})")
    if not os.path.isfile(path):
        raise CheckFailure(f"{filename} exists but is not a regular file")
    if os.path.getsize(path) == 0:
        raise CheckFailure(f"{filename} is empty (0 bytes)")

    try:
        with open(path, newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            header = [column for column in (reader.fieldnames or []) if column is not None]
            rows = list(reader)
    except UnicodeDecodeError as exc:
        raise CheckFailure(f"{filename} is not valid UTF-8: {exc}") from exc
    except csv.Error as exc:
        raise CheckFailure(f"{filename} could not be parsed as CSV: {exc}") from exc

    if not header:
        raise CheckFailure(f"{filename} has no CSV header row")
    if not rows:
        raise CheckFailure(f"{filename} contains a header but zero data rows")

    missing = [column for column in required_columns if column not in header]
    if missing:
        raise CheckFailure(f"{filename} is missing required column(s): {', '.join(missing)}")

    return rows


def cached_rows(filename: str, required_columns: tuple[str, ...] = ()) -> list[dict]:
    if filename not in _CACHE:
        _CACHE[filename] = load_rows(filename, required_columns)
    return _CACHE[filename]


def to_float(value, *, filename: str, column: str, row_number: int) -> float:
    text = (value or "").strip() if isinstance(value, str) else value
    if text is None or text == "":
        raise CheckFailure(f"{filename}: empty value in column '{column}' at data row {row_number}")
    try:
        return float(text)
    except (TypeError, ValueError):
        raise CheckFailure(
            f"{filename}: non-numeric value {value!r} in column '{column}' at data row {row_number}"
        )


def to_int(value, *, filename: str, column: str, row_number: int) -> int:
    number = to_float(value, filename=filename, column=column, row_number=row_number)
    if number != int(number):
        raise CheckFailure(
            f"{filename}: non-integer value {value!r} in column '{column}' at data row {row_number}"
        )
    return int(number)


def blank_mask(rows: list[dict], column: str) -> list[int]:
    """Return 1-based data row numbers whose ``column`` value is blank/whitespace."""
    blanks = []
    for index, row in enumerate(rows, start=1):
        value = row.get(column)
        if value is None or (isinstance(value, str) and value.strip() == ""):
            blanks.append(index)
    return blanks


# --------------------------------------------------------------------------- #
# Checks: t01_selected_indicators.csv
# --------------------------------------------------------------------------- #
def check_t01_present() -> tuple[bool, str]:
    rows = load_rows(T01, ("indicator_id", "indicator_name"))
    return True, f"{T01} is present and non-empty with {len(rows)} indicator rows"


def check_t01_columns() -> tuple[bool, str]:
    required = ("indicator_id", "indicator_name", "theme", "justification", "expected_direction")
    rows = cached_rows(T01, required)
    return True, f"{T01} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t01_unique_indicators() -> tuple[bool, str]:
    rows = cached_rows(T01, ("indicator_id",))
    ids = [(row.get("indicator_id") or "").strip() for row in rows]
    blanks = [index for index, value in enumerate(ids, start=1) if not value]
    if blanks:
        raise CheckFailure(f"{T01}: blank indicator_id at data row(s) {blanks[:5]}")
    duplicates = sorted({value for value in ids if ids.count(value) > 1})
    if duplicates:
        raise CheckFailure(f"{T01}: duplicated indicator_id(s): {', '.join(duplicates[:5])}")
    return True, f"{T01}: all {len(ids)} indicator_id values are unique and non-blank"


def check_t01_expected_direction() -> tuple[bool, str]:
    rows = cached_rows(T01, ("expected_direction",))
    invalid = []
    for index, row in enumerate(rows, start=1):
        value = (row.get("expected_direction") or "").strip()
        if value not in EXPECTED_DIRECTIONS:
            invalid.append(f"row {index}={value!r}")
    if invalid:
        raise CheckFailure(
            f"{T01}: unexpected expected_direction value(s) {', '.join(invalid[:5])}; "
            f"allowed: {', '.join(sorted(EXPECTED_DIRECTIONS))}"
        )
    return True, f"{T01}: all expected_direction values are within the allowed vocabulary"


# --------------------------------------------------------------------------- #
# Checks: t05_clean_stops.csv
# --------------------------------------------------------------------------- #
def check_t05_present() -> tuple[bool, str]:
    rows = load_rows(T05, ("stop_id", "stop_lat", "stop_lon"))
    return True, f"{T05} is present and non-empty with {len(rows)} stop rows"


def check_t05_columns() -> tuple[bool, str]:
    required = ("stop_id", "stop_name", "stop_lat", "stop_lon")
    rows = cached_rows(T05, required)
    return True, f"{T05} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t05_unique_stop_ids() -> tuple[bool, str]:
    rows = cached_rows(T05, ("stop_id",))
    ids = [(row.get("stop_id") or "").strip() for row in rows]
    blanks = [index for index, value in enumerate(ids, start=1) if not value]
    if blanks:
        raise CheckFailure(f"{T05}: blank stop_id at data row(s) {blanks[:5]}")
    duplicates = sorted({value for value in ids if ids.count(value) > 1})
    if duplicates:
        raise CheckFailure(f"{T05}: duplicated stop_id(s): {', '.join(duplicates[:5])}")
    return True, f"{T05}: {len(ids)} stop_id values are unique (stop-level grain preserved)"


def check_t05_coordinates() -> tuple[bool, str]:
    rows = cached_rows(T05, ("stop_lat", "stop_lon"))
    problems = []
    for index, row in enumerate(rows, start=1):
        lat = to_float(row.get("stop_lat"), filename=T05, column="stop_lat", row_number=index)
        lon = to_float(row.get("stop_lon"), filename=T05, column="stop_lon", row_number=index)
        if not -90.0 <= lat <= 90.0:
            problems.append(f"row {index} latitude={lat}")
        elif not -180.0 <= lon <= 180.0:
            problems.append(f"row {index} longitude={lon}")
        elif lat == 0.0 and lon == 0.0:
            problems.append(f"row {index} null island (0, 0)")
    if problems:
        raise CheckFailure(f"{T05}: invalid coordinates: {', '.join(problems[:5])}")
    return True, f"{T05}: all {len(rows)} stop coordinates are numeric and within valid ranges"


# --------------------------------------------------------------------------- #
# Checks: t08_pois_clean.csv
# --------------------------------------------------------------------------- #
def check_t08_present() -> tuple[bool, str]:
    rows = load_rows(T08, ("qid", "latitude", "longitude"))
    return True, f"{T08} is present and non-empty with {len(rows)} POI rows"


def check_t08_columns() -> tuple[bool, str]:
    required = ("qid", "label", "poi_type", "latitude", "longitude", "source")
    rows = cached_rows(T08, required)
    return True, f"{T08} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t08_qids_and_types() -> tuple[bool, str]:
    rows = cached_rows(T08, ("qid", "poi_type"))
    ids = [(row.get("qid") or "").strip() for row in rows]
    blanks = [index for index, value in enumerate(ids, start=1) if not value]
    if blanks:
        raise CheckFailure(f"{T08}: blank qid at data row(s) {blanks[:5]}")
    duplicates = sorted({value for value in ids if ids.count(value) > 1})
    if duplicates:
        raise CheckFailure(f"{T08}: duplicated qid(s): {', '.join(duplicates[:5])}")
    blank_types = blank_mask(rows, "poi_type")
    if blank_types:
        raise CheckFailure(f"{T08}: blank poi_type at data row(s) {blank_types[:5]}")
    return True, f"{T08}: {len(ids)} unique qids and no blank poi_type values"


def check_t08_coordinates() -> tuple[bool, str]:
    rows = cached_rows(T08, ("latitude", "longitude"))
    problems = []
    for index, row in enumerate(rows, start=1):
        lat = to_float(row.get("latitude"), filename=T08, column="latitude", row_number=index)
        lon = to_float(row.get("longitude"), filename=T08, column="longitude", row_number=index)
        if not -90.0 <= lat <= 90.0:
            problems.append(f"row {index} latitude={lat}")
        elif not -180.0 <= lon <= 180.0:
            problems.append(f"row {index} longitude={lon}")
        elif lat == 0.0 and lon == 0.0:
            problems.append(f"row {index} null island (0, 0)")
    if problems:
        raise CheckFailure(f"{T08}: invalid coordinates: {', '.join(problems[:5])}")
    return True, f"{T08}: all {len(rows)} POI coordinates are numeric and within valid ranges"


# --------------------------------------------------------------------------- #
# Checks: t10_accessibility_scores.csv
# --------------------------------------------------------------------------- #
def check_t10_present() -> tuple[bool, str]:
    rows = load_rows(T10, ("qid", "accessibility_score"))
    return True, f"{T10} is present and non-empty with {len(rows)} scored POI rows"


def check_t10_columns() -> tuple[bool, str]:
    required = (
        "qid",
        "label",
        "poi_type",
        "distance_m",
        "n_departures",
        "n_routes",
        "accessibility_score",
    )
    rows = cached_rows(T10, required)
    return True, f"{T10} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t10_score_range() -> tuple[bool, str]:
    rows = cached_rows(T10, ("accessibility_score",))
    out_of_range = []
    for index, row in enumerate(rows, start=1):
        score = to_float(
            row.get("accessibility_score"),
            filename=T10,
            column="accessibility_score",
            row_number=index,
        )
        if not 0.0 <= score <= 1.0:
            out_of_range.append(f"row {index}={score}")
    if out_of_range:
        raise CheckFailure(f"{T10}: accessibility_score outside [0, 1]: {', '.join(out_of_range[:5])}")
    return True, f"{T10}: all {len(rows)} accessibility_score values fall within [0, 1]"


def check_t10_inputs_nonnegative() -> tuple[bool, str]:
    rows = cached_rows(T10, ("distance_m", "n_departures", "n_routes"))
    problems = []
    for index, row in enumerate(rows, start=1):
        distance = to_float(row.get("distance_m"), filename=T10, column="distance_m", row_number=index)
        departures = to_int(
            row.get("n_departures"), filename=T10, column="n_departures", row_number=index
        )
        routes = to_int(row.get("n_routes"), filename=T10, column="n_routes", row_number=index)
        if distance < 0:
            problems.append(f"row {index} distance_m={distance}")
        if departures < 0:
            problems.append(f"row {index} n_departures={departures}")
        if routes < 0:
            problems.append(f"row {index} n_routes={routes}")
    if problems:
        raise CheckFailure(f"{T10}: negative score input(s): {', '.join(problems[:5])}")
    return True, f"{T10}: distance_m, n_departures and n_routes are non-negative integers for all rows"


def check_t10_matches_t08() -> tuple[bool, str]:
    scores = cached_rows(T10, ("qid",))
    pois = cached_rows(T08, ("qid",))
    score_ids = {(row.get("qid") or "").strip() for row in scores}
    poi_ids = {(row.get("qid") or "").strip() for row in pois}
    if score_ids != poi_ids:
        missing = sorted(poi_ids - score_ids)
        extra = sorted(score_ids - poi_ids)
        raise CheckFailure(
            f"{T10} does not cover {T08} one-to-one: "
            f"{len(missing)} POI(s) unscored (e.g. {', '.join(missing[:3])}), "
            f"{len(extra)} unknown qid(s) (e.g. {', '.join(extra[:3])})"
        )
    return True, f"{T10} contains exactly one score per {T08} POI ({len(score_ids)} qids matched)"


# --------------------------------------------------------------------------- #
# Checks: t13_city_clusters.csv
# --------------------------------------------------------------------------- #
def check_t13_present() -> tuple[bool, str]:
    rows = load_rows(T13, ("city_id", "year", "cluster_id"))
    return True, f"{T13} is present and non-empty with {len(rows)} city-year rows"


def check_t13_columns() -> tuple[bool, str]:
    required = ("city_id", "city_name", "year", "cluster_id")
    rows = cached_rows(T13, required)
    return True, f"{T13} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t13_grain() -> tuple[bool, str]:
    rows = cached_rows(T13, ("city_id", "year"))
    seen: dict[tuple[str, str], int] = {}
    duplicates = []
    blanks = []
    for index, row in enumerate(rows, start=1):
        city = (row.get("city_id") or "").strip()
        year = (row.get("year") or "").strip()
        if not city or not year:
            blanks.append(index)
            continue
        key = (city, year)
        if key in seen:
            duplicates.append(f"({city}, {year}) at rows {seen[key]} and {index}")
        else:
            seen[key] = index
    if blanks:
        raise CheckFailure(f"{T13}: blank city_id/year at data row(s) {blanks[:5]}")
    if duplicates:
        raise CheckFailure(f"{T13}: duplicated city-year key(s): {', '.join(duplicates[:5])}")
    return True, f"{T13}: unique (city_id, year) grain across {len(seen)} city-year rows"


def check_t13_cluster_ids() -> tuple[bool, str]:
    rows = cached_rows(T13, ("cluster_id",))
    cluster_ids = set()
    for index, row in enumerate(rows, start=1):
        cluster = to_int(row.get("cluster_id"), filename=T13, column="cluster_id", row_number=index)
        if cluster < 0:
            raise CheckFailure(f"{T13}: negative cluster_id {cluster} at data row {index}")
        cluster_ids.add(cluster)
    if len(cluster_ids) < 2:
        raise CheckFailure(f"{T13}: only {len(cluster_ids)} distinct cluster_id value(s); clustering degenerate")
    return True, (
        f"{T13}: non-negative integer cluster_id values; "
        f"{len(cluster_ids)} distinct clusters ({sorted(cluster_ids)})"
    )


def check_t13_years() -> tuple[bool, str]:
    rows = cached_rows(T13, ("year",))
    years = set()
    for index, row in enumerate(rows, start=1):
        year = to_int(row.get("year"), filename=T13, column="year", row_number=index)
        if not 1990 <= year <= 2100:
            raise CheckFailure(f"{T13}: implausible year {year} at data row {index}")
        years.add(year)
    return True, f"{T13}: all years within 1990-2100 (observed {min(years)}-{max(years)})"


# --------------------------------------------------------------------------- #
# Runner
# --------------------------------------------------------------------------- #
CHECKS = (
    ("t01_file_present_nonempty", check_t01_present),
    ("t01_required_columns", check_t01_columns),
    ("t01_unique_indicator_ids", check_t01_unique_indicators),
    ("t01_expected_direction_values", check_t01_expected_direction),
    ("t05_file_present_nonempty", check_t05_present),
    ("t05_required_columns", check_t05_columns),
    ("t05_unique_stop_ids", check_t05_unique_stop_ids),
    ("t05_valid_coordinates", check_t05_coordinates),
    ("t08_file_present_nonempty", check_t08_present),
    ("t08_required_columns", check_t08_columns),
    ("t08_unique_qids_and_poi_types", check_t08_qids_and_types),
    ("t08_valid_coordinates", check_t08_coordinates),
    ("t10_file_present_nonempty", check_t10_present),
    ("t10_required_columns", check_t10_columns),
    ("t10_score_range", check_t10_score_range),
    ("t10_nonnegative_inputs", check_t10_inputs_nonnegative),
    ("t10_covers_all_t08_pois", check_t10_matches_t08),
    ("t13_file_present_nonempty", check_t13_present),
    ("t13_required_columns", check_t13_columns),
    ("t13_unique_city_year_grain", check_t13_grain),
    ("t13_cluster_id_values", check_t13_cluster_ids),
    ("t13_year_values", check_t13_years),
)


def run_check(name: str, func) -> dict:
    try:
        passed, message = func()
    except CheckFailure as exc:
        return {"check_name": name, "passed": False, "message": str(exc)}
    except Exception as exc:  # defensive: no check may crash the script
        return {
            "check_name": name,
            "passed": False,
            "message": f"check raised {type(exc).__name__}: {exc}",
        }
    return {"check_name": name, "passed": bool(passed), "message": str(message)}


def main(argv: list[str] | None = None) -> int:
    del argv  # no CLI options: the script is intentionally argument-free
    results = [run_check(name, func) for name, func in CHECKS]

    os.makedirs(OUTPUTS_DIR, exist_ok=True)
    summary_path = output_path(SUMMARY_FILENAME)
    with open(summary_path, "w", encoding="utf-8") as handle:
        json.dump(results, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    n_passed = sum(1 for entry in results if entry["passed"])
    n_failed = len(results) - n_passed
    print(f"Wrote {summary_path}")
    print(f"{n_passed}/{len(results)} checks passed, {n_failed} failed")
    for entry in results:
        if not entry["passed"]:
            print(f"  FAILED {entry['check_name']}: {entry['message']}")
    return 0 if n_failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"}

