def run_check(name: str, func) -> dict:
    try:
        passed, message = func()
    except CheckFailure as exc:
        return {"check_name": name, "passed": False, "message": str(exc)}
    except Exception as exc:  # defensive: no check may crash the script
        return {
            "check_name": name,
            "passed": False,
            "message": f"check raised {type(exc).__name__}: {exc}",
        }
    return {"check_name": name, "passed": bool(passed), "message": str(message)}


def main(argv: list[str] | None = None) -> int:
    del argv  # no CLI options: the script is intentionally argument-free
    results = [run_check(name, func) for name, func in CHECKS]

    os.makedirs(OUTPUTS_DIR, exist_ok=True)
    summary_path = output_path(SUMMARY_FILENAME)
    with open(summary_path, "w", encoding="utf-8") as handle:
        json.dump(results, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    n_passed = sum(1 for entry in results if entry["passed"])
    n_failed = len(results) - n_passed
    print(f"Wrote {summary_path}")
    print(f"{n_passed}/{len(results)} checks passed, {n_failed} failed")
    for entry in results:
        if not entry["passed"]:
            print(f"  FAILED {entry['check_name']}: {entry['message']}")
    return 0 if n_failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

