    """Read a CSV output, raising :class:`CheckFailure` on any structural problem."""
    path = output_path(filename)
    if not os.path.exists(path):
        raise CheckFailure(f"{filename} is missing (expected at {path})")
    if not os.path.isfile(path):
        raise CheckFailure(f"{filename} exists but is not a regular file")
    if os.path.getsize(path) == 0:
        raise CheckFailure(f"{filename} is empty (0 bytes)")

    try:
        with open(path, newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            header = [column for column in (reader.fieldnames or []) if column is not None]
