        elif lat == 0.0 and lon == 0.0:
            problems.append(f"row {index} null island (0, 0)")
    if problems:
        raise CheckFailure(f"{T08}: invalid coordinates: {', '.join(problems[:5])}")
    return True, f"{T08}: all {len(rows)} POI coordinates are numeric and within valid ranges"


