def check_t10_score_range() -> tuple[bool, str]:
    rows = cached_rows(T10, ("accessibility_score",))
    out_of_range = []
    for index, row in enumerate(rows, start=1):
        score = to_float(
            row.get("accessibility_score"),
            filename=T10,
            column="accessibility_score",
            row_number=index,
        )
        if not 0.0 <= score <= 1.0:
            out_of_range.append(f"row {index}={score}")
    if out_of_range:
        raise CheckFailure(f"{T10}: accessibility_score outside [0, 1]: {', '.join(out_of_range[:5])}")
    return True, f"{T10}: all {len(rows)} accessibility_score values fall within [0, 1]"


def check_t10_inputs_nonnegative() -> tuple[bool, str]:
    rows = cached_rows(T10, ("distance_m", "n_departures", "n_routes"))
    problems = []
    for index, row in enumerate(rows, start=1):
        distance = to_float(row.get("distance_m"), filename=T10, column="distance_m", row_number=index)
        departures = to_int(
            row.get("n_departures"), filename=T10, column="n_departures", row_number=index
        )
        routes = to_int(row.get("n_routes"), filename=T10, column="n_routes", row_number=index)
        if distance < 0:
            problems.append(f"row {index} distance_m={distance}")
        if departures < 0:
            problems.append(f"row {index} n_departures={departures}")
        if routes < 0:
            problems.append(f"row {index} n_routes={routes}")
    if problems:
        raise CheckFailure(f"{T10}: negative score input(s): {', '.join(problems[:5])}")
    return True, f"{T10}: distance_m, n_departures and n_routes are non-negative integers for all rows"


def check_t10_matches_t08() -> tuple[bool, str]:
    scores = cached_rows(T10, ("qid",))
    pois = cached_rows(T08, ("qid",))
    score_ids = {(row.get("qid") or "").strip() for row in scores}
    poi_ids = {(row.get("qid") or "").strip() for row in pois}
    if score_ids != poi_ids:
        missing = sorted(poi_ids - score_ids)
        extra = sorted(score_ids - poi_ids)
        raise CheckFailure(
            f"{T10} does not cover {T08} one-to-one: "
            f"{len(missing)} POI(s) unscored (e.g. {', '.join(missing[:3])}), "
            f"{len(extra)} unknown qid(s) (e.g. {', '.join(extra[:3])})"
        )
    return True, f"{T10} contains exactly one score per {T08} POI ({len(score_ids)} qids matched)"


