def check_t13_present() -> tuple[bool, str]:
    rows = load_rows(T13, ("city_id", "year", "cluster_id"))
    return True, f"{T13} is present and non-empty with {len(rows)} city-year rows"


def check_t13_columns() -> tuple[bool, str]:
    required = ("city_id", "city_name", "year", "cluster_id")
    rows = cached_rows(T13, required)
    return True, f"{T13} contains all {len(required)} required columns and {len(rows)} data rows"


def check_t13_grain() -> tuple[bool, str]:
    rows = cached_rows(T13, ("city_id", "year"))
    seen: dict[tuple[str, str], int] = {}
    duplicates = []
    blanks = []
    for index, row in enumerate(rows, start=1):
        city = (row.get("city_id") or "").strip()
        year = (row.get("year") or "").strip()
        if not city or not year:
            blanks.append(index)
            continue
        key = (city, year)
        if key in seen:
            duplicates.append(f"({city}, {year}) at rows {seen[key]} and {index}")
        else:
            seen[key] = index
    if blanks:
        raise CheckFailure(f"{T13}: blank city_id/year at data row(s) {blanks[:5]}")
    if duplicates:
        raise CheckFailure(f"{T13}: duplicated city-year key(s): {', '.join(duplicates[:5])}")
    return True, f"{T13}: unique (city_id, year) grain across {len(seen)} city-year rows"


def check_t13_cluster_ids() -> tuple[bool, str]:
    rows = cached_rows(T13, ("cluster_id",))
    cluster_ids = set()
    for index, row in enumerate(rows, start=1):
        cluster = to_int(row.get("cluster_id"), filename=T13, column="cluster_id", row_number=index)
        if cluster < 0:
            raise CheckFailure(f"{T13}: negative cluster_id {cluster} at data row {index}")
        cluster_ids.add(cluster)
    if len(cluster_ids) < 2:
        raise CheckFailure(f"{T13}: only {len(cluster_ids)} distinct cluster_id value(s); clustering degenerate")
    return True, (
        f"{T13}: non-negative integer cluster_id values; "
        f"{len(cluster_ids)} distinct clusters ({sorted(cluster_ids)})"
    )


def check_t13_years() -> tuple[bool, str]:
    rows = cached_rows(T13, ("year",))
    years = set()
    for index, row in enumerate(rows, start=1):
        year = to_int(row.get("year"), filename=T13, column="year", row_number=index)
        if not 1990 <= year <= 2100:
            raise CheckFailure(f"{T13}: implausible year {year} at data row {index}")
        years.add(year)
    return True, f"{T13}: all years within 1990-2100 (observed {min(years)}-{max(years)})"


